/* HostelOS demo application. Data is stored in this browser only. */
(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const STORE = 'hostelos_v1';
  const nowISO = () => new Date().toISOString();
  const today = () => new Date().toISOString().slice(0,10);
  const dateOffset = (days, hour=18) => { const d=new Date(); d.setDate(d.getDate()+days); d.setHours(hour,0,0,0); return d.toISOString().slice(0,16); };
  const id = prefix => `${prefix}-${Math.random().toString(36).slice(2,7).toUpperCase()}${Date.now().toString().slice(-4)}`;
  const initials = name => (name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmtDate = d => d ? new Date(d.length===10 ? d+'T12:00:00' : d).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}) : '—';
  const fmtTime = d => d ? new Date(d).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}) : '—';
  const fmtDateTime = d => d ? `${fmtDate(d)} · ${fmtTime(d)}` : '—';
  const pretty = s => (s||'').replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
  const statusClass = s => ({'In Hostel':'active','Outside on Pass':'outside','On Approved Pass':'on-pass','Active':'active','Pending':'pending','Approved':'approved','Returned':'returned','Overdue':'overdue','Rejected':'rejected','Cancelled':'cancelled','Present':'present','Absent':'absent','Resolved':'resolved','Acknowledged':'neutral','Open':'critical','Inactive':'inactive','Maintenance':'warning','Full':'neutral','Available':'active'}[s] || 'neutral');
  const seed = () => {
    const students = [
      {id:'STU-1001',name:'Aarav Sharma',course:'B.Tech',department:'CSE',year:'2nd Year',section:'A',phone:'9876543210',email:'aarav@example.com',guardian:'Rajesh Sharma',guardianPhone:'9876500001',hostel:'A Block',roomId:'R-101',bed:'A',admissionDate:'2025-08-12',status:'Active'},
      {id:'STU-1002',name:'Ananya Singh',course:'B.Tech',department:'ECE',year:'2nd Year',section:'B',phone:'9876543211',email:'ananya@example.com',guardian:'Sunil Singh',guardianPhone:'9876500002',hostel:'A Block',roomId:'R-101',bed:'B',admissionDate:'2025-08-12',status:'Active'},
      {id:'STU-1003',name:'Rohan Verma',course:'B.Tech',department:'CSE',year:'3rd Year',section:'A',phone:'9876543212',email:'rohan@example.com',guardian:'Amit Verma',guardianPhone:'9876500003',hostel:'A Block',roomId:'R-102',bed:'A',admissionDate:'2024-08-10',status:'Active'},
      {id:'STU-1004',name:'Priya Gupta',course:'BCA',department:'Computer Applications',year:'1st Year',section:'A',phone:'9876543213',email:'priya@example.com',guardian:'Neeraj Gupta',guardianPhone:'9876500004',hostel:'B Block',roomId:'R-201',bed:'A',admissionDate:'2026-08-10',status:'Active'},
      {id:'STU-1005',name:'Kabir Patel',course:'B.Tech',department:'Mechanical',year:'2nd Year',section:'C',phone:'9876543214',email:'kabir@example.com',guardian:'Vijay Patel',guardianPhone:'9876500005',hostel:'B Block',roomId:'R-202',bed:'A',admissionDate:'2025-08-12',status:'Active'},
      {id:'STU-1006',name:'Meera Das',course:'B.Tech',department:'Civil',year:'2nd Year',section:'A',phone:'9876543215',email:'meera@example.com',guardian:'Arun Das',guardianPhone:'9876500006',hostel:'A Block',roomId:'R-102',bed:'B',admissionDate:'2025-08-12',status:'Active'},
      {id:'STU-1007',name:'Ishaan Kumar',course:'B.Tech',department:'CSE',year:'1st Year',section:'B',phone:'9876543216',email:'ishaan@example.com',guardian:'Ravi Kumar',guardianPhone:'9876500007',hostel:'A Block',roomId:'R-103',bed:'A',admissionDate:'2026-08-10',status:'Active'},
      {id:'STU-1008',name:'Sana Khan',course:'BBA',department:'Management',year:'1st Year',section:'A',phone:'9876543217',email:'sana@example.com',guardian:'Imran Khan',guardianPhone:'9876500008',hostel:'B Block',roomId:'R-201',bed:'B',admissionDate:'2026-08-10',status:'Active'}
    ];
    const rooms=[
      {id:'R-101',number:'101',block:'A Block',floor:'1',type:'Double sharing',capacity:2,status:'Available'},
      {id:'R-102',number:'102',block:'A Block',floor:'1',type:'Double sharing',capacity:2,status:'Available'},
      {id:'R-103',number:'103',block:'A Block',floor:'1',type:'Triple sharing',capacity:3,status:'Available'},
      {id:'R-104',number:'104',block:'A Block',floor:'1',type:'Double sharing',capacity:2,status:'Maintenance'},
      {id:'R-201',number:'201',block:'B Block',floor:'2',type:'Triple sharing',capacity:3,status:'Available'},
      {id:'R-202',number:'202',block:'B Block',floor:'2',type:'Double sharing',capacity:2,status:'Available'}
    ];
    const passes=[
      {id:'PS-2401',studentId:'STU-1003',type:'Local Pass',destination:'Market area',reason:'Personal errands',departure:dateOffset(0,8),expectedReturn:dateOffset(0,19),actualDeparture:dateOffset(0,8),actualReturn:null,status:'Active',radius:2,tracking:true,createdAt:nowISO(),remarks:''},
      {id:'PS-2402',studentId:'STU-1005',type:'Main Pass',destination:'City centre',reason:'Purchase essentials',departure:dateOffset(0,10),expectedReturn:dateOffset(0,17),actualDeparture:null,actualReturn:null,status:'Pending',radius:8,tracking:false,createdAt:nowISO(),remarks:''},
      {id:'PS-2403',studentId:'STU-1002',type:'Home Pass',destination:'Patna, Bihar',reason:'Family visit',departure:dateOffset(2,9),expectedReturn:dateOffset(4,18),actualDeparture:null,actualReturn:null,status:'Approved',radius:0,tracking:false,createdAt:nowISO(),remarks:''},
      {id:'PS-2404',studentId:'STU-1007',type:'Local Pass',destination:'Nearby pharmacy',reason:'Buy essentials',departure:dateOffset(-1,10),expectedReturn:dateOffset(-1,14),actualDeparture:dateOffset(-1,10),actualReturn:null,status:'Overdue',radius:2,tracking:true,createdAt:nowISO(),remarks:'Demo overdue pass'}
    ];
    const attendance=[];
    students.forEach((s,i)=>attendance.push({id:id('ATT'),studentId:s.id,date:today(),session:'Evening',status:i===3?'Absent':(i===0?'On Approved Pass':'Present'),markedAt:nowISO()}));
    const events=[
      {id:'EV-101',title:'Hostel Community Meetup',description:'Meet fellow residents and learn about upcoming hostel activities.',date:dateOffset(3,17).slice(0,10),time:'17:00',venue:'Common Hall',status:'Published',registrations:24},
      {id:'EV-102',title:'Clean Campus Drive',description:'Join the community for a cleaner and greener campus.',date:dateOffset(5,8).slice(0,10),time:'08:00',venue:'Main Gate',status:'Published',registrations:18},
      {id:'EV-103',title:'Indoor Games Evening',description:'Friendly games and a chance to meet your hostel mates.',date:dateOffset(8,18).slice(0,10),time:'18:00',venue:'Activity Room',status:'Published',registrations:12}
    ];
    const alerts=[
      {id:'AL-101',type:'Overdue return',severity:'High',studentId:'STU-1007',passId:'PS-2404',message:'Expected return time has passed. Confirm the student status.',createdAt:dateOffset(-1,14),status:'Open'},
      {id:'AL-102',type:'Pending approval',severity:'Normal',studentId:'STU-1005',passId:'PS-2402',message:'A Main Pass is waiting for warden review.',createdAt:nowISO(),status:'Open'}
    ];
    return {students,rooms,passes,attendance,events,alerts,locations:[],violations:[],settings:{hostelName:'HostelOS Residence',hostelLat:25.282,hostelLng:82.956,localRadius:2,mainRadius:8,trackingEnabled:true,notificationsEnabled:true,defaultAttendanceSession:'Evening',wardenName:'Warden Admin'},activity:[{id:id('LOG'),text:'Workspace initialized with demo records',time:nowISO(),tone:'blue'}]};
  };
  let db;
  try { db=JSON.parse(localStorage.getItem(STORE)); } catch(e) { db=null; }
  if(!db || !Array.isArray(db.students)) { db=seed(); save(); }
  function save(){ localStorage.setItem(STORE,JSON.stringify(db)); }
  function log(text,tone='blue'){ db.activity.unshift({id:id('LOG'),text,time:nowISO(),tone}); db.activity=db.activity.slice(0,30); save(); }
  function toast(message,type='success'){ const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3500); }
  function student(sid){ return db.students.find(s=>s.id===sid); }
  function room(rid){ return db.rooms.find(r=>r.id===rid); }
  function roomOccupants(rid,excludeId=null){return db.students.filter(s=>s.roomId===rid&&s.status==='Active'&&s.id!==excludeId);}
  function roomCount(rid){return roomOccupants(rid).length;}
  function studentPass(sid){return db.passes.filter(p=>p.studentId===sid).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));}
  function activePass(sid){return db.passes.find(p=>p.studentId===sid&&p.status==='Active');}
  function movementStatus(s){const p=activePass(s.id);if(p)return 'Outside on Pass';if(db.passes.some(p=>p.studentId===s.id&&p.status==='Overdue'))return 'Overdue';return s.status==='Active'?'In Hostel':'Inactive';}
  function checkOverdue(){let changed=false;db.passes.forEach(p=>{if(['Active','Approved'].includes(p.status)&&p.expectedReturn&&new Date(p.expectedReturn)<new Date()&&p.status==='Active'){p.status='Overdue';p.tracking=false;db.alerts.unshift({id:id('AL'),type:'Overdue return',severity:'High',studentId:p.studentId,passId:p.id,message:'The expected return time has passed.',createdAt:nowISO(),status:'Open'});changed=true;}});if(changed){save();}}
  checkOverdue();
  let currentPage='dashboard', map=null, mapLayer=null, modalConfig=null, currentStudentFilter='';
  const pageTitles={dashboard:'Dashboard',students:'Students',rooms:'Rooms & Beds',passes:'Pass management',movement:'Live movement',attendance:'Attendance',events:'Events',alerts:'Alerts',settings:'Settings'};
  function updateBadges(){const pending=db.passes.filter(p=>p.status==='Pending').length;const alerts=db.alerts.filter(a=>a.status==='Open').length;$('#pendingBadge').textContent=pending;$('#alertBadge').textContent=alerts;$('#topAlertDot').style.display=alerts?'block':'none';}
  function go(page){currentPage=page;$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumbTitle').textContent=pageTitles[page]||page;renderPage();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});}
  function heading(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">HOSTELOS WORKSPACE</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
  function btn(label,action,kind='primary',icon='＋'){return `<button class="btn btn-${kind}" data-action="${action}">${icon?`<span>${icon}</span>`:''}${label}</button>`;}
  function stat(label,value,foot,icon,tone){return `<div class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon tone-${tone}">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
  function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action?`<button class="link-btn" data-action="${action}">View all ↗</button>`:''}</div>${body}</section>`;}
  function status(s){return `<span class="status ${statusClass(s)}">${esc(s)}</span>`;}
  function studentCell(s){return `<div class="student-cell"><div class="mini-avatar">${initials(s.name)}</div><div><strong>${esc(s.name)}</strong><small>${esc(s.id)}</small></div></div>`;}
  function studentName(sid){return student(sid)?.name||'Unknown student';}
  function activityMarkup(a){const tones={blue:'tone-blue',green:'tone-green',orange:'tone-orange',red:'tone-red',purple:'tone-purple'};return `<div class="activity"><div class="activity-dot ${tones[a.tone]||'tone-blue'}">✦</div><div class="activity-copy"><p>${esc(a.text)}</p><small>${fmtDateTime(a.time)}</small></div></div>`;}
  function dashboardPage(){
    const activeStudents=db.students.filter(s=>s.status==='Active'),outside=activeStudents.filter(s=>movementStatus(s)==='Outside on Pass').length,overdue=db.passes.filter(p=>p.status==='Overdue').length,pending=db.passes.filter(p=>p.status==='Pending').length,occupied=db.rooms.reduce((n,r)=>n+roomCount(r.id),0),capacity=db.rooms.reduce((n,r)=>n+Number(r.capacity),0),present=db.attendance.filter(a=>a.date===today()&&a.status==='Present').length,marked=db.attendance.filter(a=>a.date===today()).length,attendancePct=marked?Math.round(present/marked*100):0;
    const roomBody=`<div class="chart-summary"><div class="chart-total"><strong>${occupied}<span style="font-size:14px;color:#9aa4b7">/${capacity}</span></strong><span>Beds currently occupied</span></div><div class="chart-legend"><div class="legend-item"><span class="legend-dot" style="background:#6579f3"></span>Occupied <strong>${occupied}</strong></div><div class="legend-item"><span class="legend-dot" style="background:#e9edf5"></span>Vacant <strong>${Math.max(0,capacity-occupied)}</strong></div><div class="legend-item"><span class="legend-dot" style="background:#e8a94e"></span>Maintenance rooms <strong>${db.rooms.filter(r=>r.status==='Maintenance').length}</strong></div></div></div><div class="bar-chart">${db.rooms.slice(0,6).map(r=>`<div class="bar-group"><div class="bar alt" style="height:${Math.min(100,roomCount(r.id)/Math.max(1,r.capacity)*100)}%"></div><div class="bar" style="height:${Math.max(3,100-roomCount(r.id)/Math.max(1,r.capacity)*100)}%"></div></div>`).join('')}</div><div class="bar-labels">${db.rooms.slice(0,6).map(r=>`<span>${esc(r.number)}</span>`).join('')}</div>`;
    const passRows=db.passes.filter(p=>['Pending','Overdue','Active'].includes(p.status)).slice(0,5);
    const passBody=`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Pass type</th><th>Return</th><th>Status</th></tr></thead><tbody>${passRows.map(p=>`<tr><td>${studentCell(student(p.studentId)||{name:'Unknown',id:p.studentId})}</td><td><span class="pass-type">${esc(p.type)}</span></td><td>${fmtDateTime(p.expectedReturn)}</td><td>${status(p.status)}</td></tr>`).join('')||`<tr><td colspan="4"><div class="empty-state">No active pass actions.</div></td></tr>`}</tbody></table></div>`;
    const activityBody=`<div class="panel-body"><div class="activity-list">${db.activity.slice(0,5).map(activityMarkup).join('')||'<div class="empty-state">No activity yet.</div>'}</div></div>`;
    return `${heading('Good morning, Warden 👋',`Here’s what’s happening at ${esc(db.settings.hostelName)} today.`,`${btn('Add student','add-student','primary','＋')}${btn('Create pass','add-pass','ghost','↗')}`)}
      <div class="stat-grid">${stat('Total students',activeStudents.length,'Active hostel residents','♙','blue')}${stat('Outside on pass',outside,`${overdue} overdue return${overdue===1?'':'s'}`,'↗','orange')}${stat('Available beds',Math.max(0,capacity-occupied),'Across all registered rooms','▤','green')}${stat('Pending approvals',pending,`${db.alerts.filter(a=>a.status==='Open').length} open alerts`,'♧','purple')}</div>
      <div class="dashboard-grid">${panel('Room occupancy','Current bed allocation across registered rooms',`<div class="panel-body">${roomBody}</div>`,'rooms')}${panel('Recent activity','Latest updates in your workspace',activityBody,'alerts')}</div>
      ${panel('Passes needing attention','Review pending approvals and students who may need a follow-up',passBody,'passes')}
      <div class="dashboard-grid section-gap">${panel('Today at a glance','Attendance and resident overview',`<div class="panel-body"><div class="mini-stat-row"><div class="mini-stat"><span>Present today</span><strong>${present}</strong></div><div class="mini-stat"><span>Marked records</span><strong>${marked}</strong></div><div class="mini-stat"><span>Attendance rate</span><strong>${attendancePct}%</strong></div></div><button class="btn btn-soft" data-page="attendance">Open attendance →</button></div>`)}${panel('Upcoming events','What’s coming up in the hostel',`<div class="panel-body"><div class="activity-list">${db.events.filter(e=>e.status==='Published').sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3).map(e=>`<div class="activity"><div class="activity-dot tone-purple">▣</div><div class="activity-copy"><p><strong>${esc(e.title)}</strong></p><small>${fmtDate(e.date)} · ${esc(e.time)} · ${esc(e.venue)}</small></div></div>`).join('')||'<div class="empty-state">No upcoming events.</div>'}</div></div>`,'events')}</div>`;
  }
  function studentsPage(){
    const q=currentStudentFilter.toLowerCase();const rows=db.students.filter(s=>[s.name,s.id,s.department,s.course,s.roomId,s.phone].join(' ').toLowerCase().includes(q));
    const body=rows.map(s=>`<tr><td>${studentCell(s)}</td><td>${esc(s.course)}<small style="display:block;color:#9aa4b7;margin-top:3px">${esc(s.department)} · ${esc(s.year)}</small></td><td>${esc(room(s.roomId)?.number||'Unassigned')} <small style="color:#9aa4b7">· ${esc(s.bed||'—')}</small></td><td>${esc(s.phone||'—')}</td><td>${status(s.status)}</td><td>${status(movementStatus(s))}</td><td><div class="row-actions"><button class="action-btn" data-action="view-student" data-id="${s.id}" title="View">⌕</button><button class="action-btn" data-action="edit-student" data-id="${s.id}" title="Edit">✎</button><button class="action-btn" data-action="delete-student" data-id="${s.id}" title="Deactivate">⋯</button></div></td></tr>`).join('');
    return `${heading('Students','Manage resident profiles, academic details and room assignments.',btn('Add student','add-student','primary','＋'))}<div class="mini-stat-row"><div class="mini-stat"><span>Total records</span><strong>${db.students.length}</strong></div><div class="mini-stat"><span>Active residents</span><strong>${db.students.filter(s=>s.status==='Active').length}</strong></div><div class="mini-stat"><span>Unassigned students</span><strong>${db.students.filter(s=>!s.roomId).length}</strong></div></div><section class="panel"><div class="table-tools"><input class="table-search" id="studentSearch" placeholder="Search name, ID, department..." value="${esc(currentStudentFilter)}"><select class="table-select" id="studentStatusFilter"><option value="">All statuses</option><option>Active</option><option>Inactive</option></select><div class="tools-spacer"></div><button class="btn btn-ghost" data-action="export-students">↓ Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Course / department</th><th>Room / bed</th><th>Phone</th><th>Student status</th><th>Movement</th><th>Actions</th></tr></thead><tbody id="studentRows">${body||`<tr><td colspan="7"><div class="empty-state"><strong>No students found</strong>Try a different search or add a student.</div></td></tr>`}</tbody></table></div></section>`;
  }
  function roomsPage(){
    const occupied=db.rooms.reduce((n,r)=>n+roomCount(r.id),0),capacity=db.rooms.reduce((n,r)=>n+Number(r.capacity),0);
    const cards=db.rooms.map(r=>{const count=roomCount(r.id),vacant=Math.max(0,r.capacity-count),pct=Math.min(100,count/r.capacity*100);return `<div class="room-card"><div class="room-card-top"><div><div class="room-number">Room ${esc(r.number)}</div><div class="room-sub">${esc(r.block)} · Floor ${esc(r.floor)}</div></div>${status(r.status==='Maintenance'?'Maintenance':count>=r.capacity?'Full':'Available')}</div><div class="occupancy-line"><div class="occupancy-fill" style="width:${pct}%;${r.status==='Maintenance'?'background:#e6a23c':''}"></div></div><div class="room-foot"><span>${count} of ${r.capacity} beds used</span><strong>${vacant} vacant</strong></div><div style="display:flex;gap:7px;margin-top:14px"><button class="btn btn-ghost btn-sm" data-action="edit-room" data-id="${r.id}">Edit room</button><button class="btn btn-soft btn-sm" data-action="room-students" data-id="${r.id}">Residents</button></div></div>`}).join('');
    return `${heading('Rooms & Beds','Keep track of room capacity, allocations and availability.',btn('Add room','add-room','primary','＋'))}<div class="mini-stat-row"><div class="mini-stat"><span>Total rooms</span><strong>${db.rooms.length}</strong></div><div class="mini-stat"><span>Occupied beds</span><strong>${occupied}</strong></div><div class="mini-stat"><span>Vacant beds</span><strong>${Math.max(0,capacity-occupied)}</strong></div></div><section class="panel"><div class="panel-head"><div><h2>Room directory</h2><p>Bed availability updates from student allocations.</p></div><select class="table-select" id="roomBlockFilter"><option value="">All blocks</option>${[...new Set(db.rooms.map(r=>r.block))].map(b=>`<option>${esc(b)}</option>`).join('')}</select></div><div class="room-grid" id="roomCards">${cards}</div></section>`;
  }
  function passesPage(){
    const filter=window.passFilter||'All';const passes=db.passes.filter(p=>filter==='All'||p.status===filter).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
    const rows=passes.map(p=>`<tr><td><strong style="color:var(--ink)">${esc(p.id)}</strong><small style="display:block;color:#9aa4b7;margin-top:3px">${fmtDate(p.createdAt)}</small></td><td>${studentCell(student(p.studentId)||{name:'Unknown',id:p.studentId})}</td><td><span class="pass-type">${esc(p.type)}</span></td><td>${esc(p.destination)}</td><td>${fmtDateTime(p.expectedReturn)}</td><td>${status(p.status)}</td><td><div class="row-actions">${p.status==='Pending'?`<button class="btn btn-soft btn-sm" data-action="approve-pass" data-id="${p.id}">Approve</button><button class="action-btn" data-action="reject-pass" data-id="${p.id}" title="Reject">×</button>`:''}${p.status==='Approved'?`<button class="btn btn-soft btn-sm" data-action="depart-pass" data-id="${p.id}">Departure</button>`:''}${['Active','Overdue'].includes(p.status)?`<button class="btn btn-primary btn-sm" data-action="return-pass" data-id="${p.id}">Mark returned</button>`:''}<button class="action-btn" data-action="view-pass" data-id="${p.id}" title="View">⌕</button></div></td></tr>`).join('');
    return `${heading('Pass management','Review requests, record departures and close returns.',btn('Create pass','add-pass','primary','＋'))}<div class="notice info">Pass tracking is a demo workflow. Live GPS requires a student-side client, explicit permission and a backend. Sample records are clearly for demonstration.</div><div class="mini-stat-row"><div class="mini-stat"><span>Pending</span><strong>${db.passes.filter(p=>p.status==='Pending').length}</strong></div><div class="mini-stat"><span>Active outside</span><strong>${db.passes.filter(p=>p.status==='Active').length}</strong></div><div class="mini-stat"><span>Overdue</span><strong>${db.passes.filter(p=>p.status==='Overdue').length}</strong></div></div><section class="panel"><div class="table-tools"><div class="filter-pills">${['All','Pending','Approved','Active','Overdue','Returned','Rejected','Cancelled'].map(f=>`<button class="pill ${(window.passFilter||'All')===f?'active':''}" data-action="pass-filter" data-filter="${f}">${f}</button>`).join('')}</div><div class="tools-spacer"></div><button class="btn btn-ghost" data-action="export-passes">↓ Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Pass ID</th><th>Student</th><th>Type</th><th>Destination</th><th>Expected return</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows||`<tr><td colspan="7"><div class="empty-state"><strong>No passes in this view</strong>Create a pass or select another filter.</div></td></tr>`}</tbody></table></div></section>`;
  }
  function movementPage(){
    const active=db.passes.filter(p=>['Active','Overdue'].includes(p.status));
    return `${heading('Live movement','Monitor active pass records and permitted areas.',btn('Refresh status','refresh-movement','ghost','↻'))}<div class="notice danger"><strong>Demo mode:</strong> Locations shown here are simulated or last reported records, not live GPS. A browser dashboard cannot independently track student phones.</div><div class="map-layout"><section class="panel"><div class="panel-head"><div><h2>Hostel movement map</h2><p>${esc(db.settings.hostelName)} · configured location</p></div><span class="status neutral">Demo map</span></div><div class="map-box" id="movementMap"><div class="map-placeholder"><div><div style="font-size:36px">⌖</div><strong>Interactive map</strong><p>Map tiles load when internet access is available. Student pins are only displayed for recorded demo coordinates.</p><button class="btn btn-primary" data-action="load-map">Load map</button></div></div></div></section><section class="panel"><div class="panel-head"><div><h2>Active pass holders</h2><p>${active.length} record(s) outside or overdue</p></div></div><div class="panel-body"><div class="movement-list">${active.map(p=>`<div class="movement-row"><div class="mini-avatar">${initials(studentName(p.studentId))}</div><div class="movement-info"><strong>${esc(studentName(p.studentId))}</strong><small>${esc(p.type)} · Return ${fmtTime(p.expectedReturn)}</small><small>${esc(p.destination)}</small></div>${status(p.status)}</div>`).join('')||'<div class="empty-state"><strong>No active pass holders</strong>Approved departures will appear here.</div>'}</div></div></section></div><section class="panel section-gap"><div class="panel-head"><div><h2>Location update simulator</h2><p>For testing geofence logic only. No real phone location is collected.</p></div></div><div class="panel-body"><div class="form-grid"><div class="field"><label>Student with active pass</label><select id="simStudent">${active.map(p=>`<option value="${p.id}">${esc(studentName(p.studentId))} · ${esc(p.type)}</option>`).join('')||'<option value="">No active pass</option>'}</select></div><div class="field"><label>Simulated result</label><select id="simResult"><option value="inside">Inside permitted area</option><option value="outside">Outside permitted area (create alert)</option><option value="stale">Stale / unavailable update</option></select></div></div><div style="margin-top:15px"><button class="btn btn-primary" data-action="simulate-location">Record simulated update</button></div></div></section>`;
  }
  function attendancePage(){
    const date=window.attendanceDate||today(),session=window.attendanceSession||db.settings.defaultAttendanceSession||'Evening';
    const records=db.attendance.filter(a=>a.date===date&&a.session===session);
    const rows=db.students.filter(s=>s.status==='Active').map(s=>{const a=records.find(x=>x.studentId===s.id);return `<tr><td>${studentCell(s)}</td><td>${esc(room(s.roomId)?.number||'—')}</td><td>${a?status(a.status):'<span class="status neutral">Not marked</span>'}</td><td><select class="table-select attendance-choice" data-student="${s.id}" style="min-width:145px"><option value="">Choose status</option>${['Present','Absent','On Approved Pass'].map(v=>`<option ${a?.status===v?'selected':''}>${v}</option>`).join('')}</select></td></tr>`}).join('');
    const present=records.filter(a=>a.status==='Present').length,absent=records.filter(a=>a.status==='Absent').length,onpass=records.filter(a=>a.status==='On Approved Pass').length;
    return `${heading('Attendance','Record daily attendance and review resident attendance history.',btn('Export report','export-attendance','ghost','↓'))}<div class="mini-stat-row"><div class="mini-stat"><span>Present</span><strong>${present}</strong></div><div class="mini-stat"><span>Absent</span><strong>${absent}</strong></div><div class="mini-stat"><span>On approved pass</span><strong>${onpass}</strong></div></div><section class="panel"><div class="table-tools"><div class="field" style="display:flex;align-items:center;gap:8px"><label for="attendanceDate">Date</label><input type="date" id="attendanceDate" class="table-select" value="${date}"></div><div class="field" style="display:flex;align-items:center;gap:8px"><label for="attendanceSession">Session</label><select id="attendanceSession" class="table-select">${['Morning','Afternoon','Evening','Night'].map(v=>`<option ${session===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="tools-spacer"></div><button class="btn btn-primary" data-action="save-attendance">Save attendance</button></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Room</th><th>Current record</th><th>Mark status</th></tr></thead><tbody>${rows}</tbody></table></div></section><section class="panel section-gap"><div class="panel-head"><div><h2>Recent attendance history</h2><p>Latest saved attendance records</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Session</th><th>Student</th><th>Status</th><th>Recorded at</th></tr></thead><tbody>${db.attendance.slice().sort((a,b)=>new Date(b.markedAt)-new Date(a.markedAt)).slice(0,10).map(a=>`<tr><td>${fmtDate(a.date)}</td><td>${esc(a.session)}</td><td>${esc(studentName(a.studentId))}</td><td>${status(a.status)}</td><td>${fmtDateTime(a.markedAt)}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty-state">No attendance records.</div></td></tr>'}</tbody></table></div></section>`;
  }
  function eventsPage(){
    const events=db.events.slice().sort((a,b)=>a.date.localeCompare(b.date));
    return `${heading('Events & announcements','Publish hostel activities and keep residents informed.',btn('Create event','add-event','primary','＋'))}<section class="panel"><div class="panel-head"><div><h2>Event calendar</h2><p>${events.filter(e=>e.status==='Published').length} published event(s)</p></div><button class="btn btn-ghost btn-sm" data-action="export-events">↓ Export CSV</button></div><div class="event-grid">${events.map(e=>`<article class="event-card"><div class="event-date">${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'}).toUpperCase()}<strong>${new Date(e.date+'T12:00:00').getDate()}</strong></div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><div class="event-meta"><span>⌖ ${esc(e.venue)} · ${esc(e.time)}</span>${status(e.status)}</div><div style="display:flex;gap:7px;margin-top:13px"><button class="btn btn-ghost btn-sm" data-action="edit-event" data-id="${e.id}">Edit</button><button class="btn btn-danger btn-sm" data-action="delete-event" data-id="${e.id}">Delete</button></div></article>`).join('')||'<div class="empty-state">No events yet.</div>'}</div></section>`;
  }
  function alertsPage(){
    const alerts=db.alerts.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
    const open=alerts.filter(a=>a.status==='Open').length;
    return `${heading('Alerts & notifications','Review issues, acknowledge alerts and record resolutions.',`<button class="btn btn-ghost" data-action="clear-resolved">Clear resolved</button>`)}<div class="mini-stat-row"><div class="mini-stat"><span>Open alerts</span><strong>${open}</strong></div><div class="mini-stat"><span>High priority</span><strong>${alerts.filter(a=>a.severity==='High'&&a.status==='Open').length}</strong></div><div class="mini-stat"><span>Resolved</span><strong>${alerts.filter(a=>a.status==='Resolved').length}</strong></div></div><section class="panel"><div class="panel-head"><div><h2>Alert inbox</h2><p>Location gaps are not automatically treated as violations.</p></div><select class="table-select" id="alertFilter"><option value="">All alerts</option><option>Open</option><option>Acknowledged</option><option>Resolved</option></select></div><div id="alertList">${alerts.map(a=>`<div class="alert-item" data-alert-status="${a.status}"><div class="alert-symbol ${a.severity==='High'?'tone-red':a.status==='Resolved'?'tone-green':'tone-orange'}">${a.severity==='High'?'!':'♧'}</div><div class="alert-copy"><strong>${esc(a.type)} · ${esc(studentName(a.studentId))}</strong><p>${esc(a.message)}</p><small>${fmtDateTime(a.createdAt)} · ${esc(a.id)} · ${esc(a.status)}</small></div><div class="alert-actions">${a.status!=='Resolved'?`<button class="btn btn-ghost btn-sm" data-action="ack-alert" data-id="${a.id}">${a.status==='Open'?'Acknowledge':'Resolve'}</button>`:status('Resolved')}</div></div>`).join('')||'<div class="empty-state"><strong>All clear</strong>No alerts to display.</div>'}</div></section>`;
  }
  function settingsPage(){
    const s=db.settings;
    return `${heading('Settings','Configure hostel details and rules for the prototype.',btn('Save settings','save-settings','primary','✓'))}<div class="notice info">These settings affect this browser’s demo data only. Production rules and user permissions must be enforced by a backend.</div><section class="panel"><div class="settings-section"><h3>Hostel profile</h3><p>Basic information shown across your admin workspace.</p><div class="form-grid"><div class="field"><label>Hostel name</label><input id="setHostelName" value="${esc(s.hostelName)}"></div><div class="field"><label>Warden display name</label><input id="setWardenName" value="${esc(s.wardenName)}"></div><div class="field"><label>Hostel latitude</label><input id="setLat" type="number" step="any" value="${s.hostelLat}"></div><div class="field"><label>Hostel longitude</label><input id="setLng" type="number" step="any" value="${s.hostelLng}"></div></div></div><div class="settings-section"><h3>Pass policies</h3><p>Set default distance limits used by the demo simulator.</p><div class="form-grid"><div class="field"><label>Local Pass radius (km)</label><input id="setLocalRadius" type="number" min=".1" step=".1" value="${s.localRadius}"></div><div class="field"><label>Main Pass radius (km)</label><input id="setMainRadius" type="number" min=".1" step=".1" value="${s.mainRadius}"></div></div><div class="setting-row"><div><strong>Movement tracking feature</strong><small>Allows the demo UI to simulate active-pass location workflows.</small></div><button class="toggle ${s.trackingEnabled?'on':''}" data-action="toggle-setting" data-key="trackingEnabled" aria-label="Toggle tracking"></button></div><div class="setting-row"><div><strong>In-app alerts</strong><small>Display alert indicators in the workspace.</small></div><button class="toggle ${s.notificationsEnabled?'on':''}" data-action="toggle-setting" data-key="notificationsEnabled" aria-label="Toggle notifications"></button></div></div><div class="settings-section"><h3>Data & demo</h3><p>Export a backup or restore the original demonstration records.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-ghost" data-action="backup-data">↓ Download JSON backup</button><button class="btn btn-danger" data-action="reset-data">Restore demo data</button></div></div></section>`;
  }
  function renderPage(){updateBadges();const renderers={dashboard:dashboardPage,students:studentsPage,rooms:roomsPage,passes:passesPage,movement:movementPage,attendance:attendancePage,events:eventsPage,alerts:alertsPage,settings:settingsPage};$('#pageContent').innerHTML=(renderers[currentPage]||dashboardPage)();if(currentPage==='movement'&&map){map.remove();map=null;}}
  const fields={
    student:[['id','Student ID','text',true],['name','Full name','text',true],['course','Course','select',true,['B.Tech','BCA','BBA','MCA','Other']],['department','Department','select',true,['CSE','ECE','Electrical','Mechanical','Civil','Biotechnology','Computer Applications','Management','Other']],['year','Year','select',true,['1st Year','2nd Year','3rd Year','4th Year','Other']],['section','Section','text',false],['phone','Phone number','tel',false],['email','Email','email',false],['guardian','Guardian name','text',false],['guardianPhone','Guardian phone','tel',false],['hostel','Hostel / block','text',true],['roomId','Room','select',false,'rooms'],['bed','Bed label','text',false],['admissionDate','Admission date','date',false],['status','Status','select',true,['Active','Inactive']]],
    room:[['number','Room number','text',true],['block','Block / building','text',true],['floor','Floor','text',true],['type','Room type','select',true,['Single sharing','Double sharing','Triple sharing','Dormitory']],['capacity','Bed capacity','number',true],['status','Room status','select',true,['Available','Maintenance']]],
    pass:[['studentId','Student','select',true,'students'],['type','Pass type','select',true,['Local Pass','Main Pass','Home Pass']],['destination','Destination','text',true],['reason','Reason','textarea',true],['departure','Planned departure','datetime-local',true],['expectedReturn','Expected return','datetime-local',true],['remarks','Warden remarks','textarea',false]],
    event:[['title','Event title','text',true],['description','Description','textarea',true],['date','Date','date',true],['time','Time','time',true],['venue','Venue','text',true],['status','Status','select',true,['Published','Draft','Cancelled']],['registrations','Expected / registered participants','number',false]]
  };
  function formField(f,value=''){
    const [name,label,type,required,opts]=f;let input='';
    if(type==='select'){let options='';if(opts==='rooms')options='<option value="">Unassigned</option>'+db.rooms.filter(r=>r.status!=='Maintenance').map(r=>`<option value="${r.id}" ${value===r.id?'selected':''}>${esc(r.number)} · ${esc(r.block)} (${roomCount(r.id)} / ${r.capacity})</option>`).join('');else if(opts==='students')options=db.students.filter(s=>s.status==='Active').map(s=>`<option value="${s.id}" ${value===s.id?'selected':''}>${esc(s.name)} · ${esc(s.id)}</option>`).join('');else options=opts.map(v=>`<option ${value===v?'selected':''}>${esc(v)}</option>`).join('');input=`<select name="${name}" ${required?'required':''}>${options}</select>`;}
    else if(type==='textarea')input=`<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea>`;
    else input=`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${name==='capacity'?'min="1" max="20"':''} ${name==='registrations'?'min="0"':''}>`;
    return `<div class="field ${type==='textarea'?'full':''}"><label>${label}${required?' *':''}</label>${input}</div>`;
  }
  function openModal(title,subtitle,body,config){modalConfig=config;$('#modalTitle').textContent=title;$('#modalSubtitle').textContent=subtitle;$('#modalBody').innerHTML=body;$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false');}
  function closeModal(){$('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true');modalConfig=null;}
  function recordForm(type,record=null){
    const fs=fields[type];const isEdit=!!record;
    const body=`<div class="form-grid">${fs.map(f=>formField(f,record?.[f[0]]??(f[0]==='id'&&type==='student'?`STU-${Date.now().toString().slice(-6)}`:f[0]==='capacity'?'2':f[0]==='registrations'?'0':f[0]==='departure'?dateOffset(0,15):f[0]==='expectedReturn'?dateOffset(0,19):f[0]==='date'?today():f[0]==='status'&&type==='student'?'Active':f[0]==='status'&&type==='event'?'Published':''))).join('')}</div>`;
    openModal(`${isEdit?'Edit':'Add'} ${type==='student'?'student':type==='room'?'room':type==='pass'?'pass':'event'}`,isEdit?'Update the record details below.':'Complete the required fields to create a record.',body,{type,record});
  }
  function viewStudent(s){const ps=studentPass(s.id);const ats=db.attendance.filter(a=>a.studentId===s.id).slice(-5);openModal(s.name,`${s.id} · ${s.course} · ${s.department}`,`<div class="mini-stat-row"><div class="mini-stat"><span>Room / bed</span><strong>${esc(room(s.roomId)?.number||'—')} / ${esc(s.bed||'—')}</strong></div><div class="mini-stat"><span>Passes</span><strong>${ps.length}</strong></div><div class="mini-stat"><span>Status</span><strong style="font-size:12px">${esc(movementStatus(s))}</strong></div></div><div class="form-grid"><div class="field"><label>Phone</label><input readonly value="${esc(s.phone||'—')}"></div><div class="field"><label>Email</label><input readonly value="${esc(s.email||'—')}"></div><div class="field"><label>Guardian</label><input readonly value="${esc(s.guardian||'—')}"></div><div class="field"><label>Guardian phone</label><input readonly value="${esc(s.guardianPhone||'—')}"></div><div class="field"><label>Hostel / block</label><input readonly value="${esc(s.hostel||room(s.roomId)?.block||'—')}"></div><div class="field"><label>Admission date</label><input readonly value="${esc(fmtDate(s.admissionDate))}"></div></div><h3 style="font-size:12px;margin:20px 0 8px">Recent passes</h3>${ps.slice(0,4).map(p=>`<div class="setting-row"><div><strong>${esc(p.type)} · ${esc(p.destination)}</strong><small>${fmtDateTime(p.expectedReturn)}</small></div>${status(p.status)}</div>`).join('')||'<p style="font-size:11px;color:#9aa4b7">No pass history.</p>'}<h3 style="font-size:12px;margin:20px 0 8px">Recent attendance</h3>${ats.map(a=>`<div class="setting-row"><div><strong>${fmtDate(a.date)} · ${esc(a.session)}</strong></div>${status(a.status)}</div>`).join('')||'<p style="font-size:11px;color:#9aa4b7">No attendance history.</p>'}`,null);$('#saveModal').style.display='none';$('#cancelModal').textContent='Close';}
  function viewPass(p){openModal(`Pass ${p.id}`,`${studentName(p.studentId)} · ${p.type}`,`<div class="form-grid"><div class="field"><label>Destination</label><input readonly value="${esc(p.destination)}"></div><div class="field"><label>Status</label><input readonly value="${esc(p.status)}"></div><div class="field"><label>Planned departure</label><input readonly value="${esc(fmtDateTime(p.departure))}"></div><div class="field"><label>Expected return</label><input readonly value="${esc(fmtDateTime(p.expectedReturn))}"></div><div class="field"><label>Actual departure</label><input readonly value="${esc(fmtDateTime(p.actualDeparture))}"></div><div class="field"><label>Actual return</label><input readonly value="${esc(fmtDateTime(p.actualReturn))}"></div><div class="field full"><label>Reason</label><textarea readonly>${esc(p.reason||'—')}</textarea></div><div class="field full"><label>Warden remarks</label><textarea readonly>${esc(p.remarks||'—')}</textarea></div></div>`,null);$('#saveModal').style.display='none';$('#cancelModal').textContent='Close';}
  function saveForm(e){e.preventDefault();if(!modalConfig)return;const {type,record}=modalConfig;const fd=new FormData(e.target);const data=Object.fromEntries(fd.entries());const list=type==='student'?'students':type==='room'?'rooms':type==='pass'?'passes':'events';if(type==='student'){if(!data.id.trim())return toast('Student ID is required','error');if(db.students.some(s=>s.id===data.id&&s.id!==record?.id))return toast('Student ID already exists','error');if(data.roomId){const r=room(data.roomId);if(!r)return toast('Selected room does not exist','error');if(roomCount(r.id,record?.id)>=Number(r.capacity))return toast('This room is at capacity','error');if(r.status==='Maintenance')return toast('Cannot allocate a bed in a maintenance room','error');const taken=roomOccupants(r.id,record?.id).some(s=>s.bed&&s.bed===data.bed);if(data.bed&&taken)return toast('That bed label is already assigned in this room','error');}if(!data.bed&&data.roomId){const used=new Set(roomOccupants(data.roomId,record?.id).map(s=>s.bed));const candidates='ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');data.bed=candidates.find(x=>!used.has(x))||`Bed-${used.size+1}`;}data.admissionDate=data.admissionDate||today();data.status=data.status||'Active';}
    if(type==='room'){data.capacity=Number(data.capacity);if(!Number.isInteger(data.capacity)||data.capacity<1||data.capacity>20)return toast('Capacity must be between 1 and 20','error');if(record&&roomCount(record.id)>data.capacity)return toast('Capacity cannot be less than current occupancy','error');if(!data.id)data.id=id('R');else data.id=record?.id||id('R');if(db.rooms.some(r=>r.number===data.number&&r.block===data.block&&r.id!==record?.id))return toast('Room number already exists in this block','error');}
    if(type==='pass'){if(new Date(data.expectedReturn)<=new Date(data.departure))return toast('Return time must be after departure','error');data.id=id('PS');data.status='Pending';data.radius=data.type==='Local Pass'?Number(db.settings.localRadius):data.type==='Main Pass'?Number(db.settings.mainRadius):0;data.tracking=false;data.actualDeparture=null;data.actualReturn=null;data.createdAt=nowISO();data.reason=data.reason||'';data.remarks=data.remarks||'';}
    if(type==='event'){data.id=record?.id||id('EV');data.registrations=Number(data.registrations||0);}
    if(record){const i=db[list].findIndex(x=>x.id===record.id);if(i>=0)db[list][i]={...db[list][i],...data};log(`${type} updated: ${data.name||data.number||data.title||data.id}`,'green');}
    else{db[list].unshift(data);log(`${type} created: ${data.name||data.number||data.title||data.id}`,'green');if(type==='pass')db.alerts.unshift({id:id('AL'),type:'Pending approval',severity:'Normal',studentId:data.studentId,passId:data.id,message:`${data.type} is waiting for warden review.`,createdAt:nowISO(),status:'Open'});}
    save();closeModal();renderPage();toast(`${pretty(type)} ${record?'updated':'created'} successfully.`);$('#saveModal').style.display='';$('#cancelModal').textContent='Cancel';
  }
  function confirmAction(title,message,callback){openModal(title,message,`<p style="font-size:12px;line-height:1.7;color:#77839b">${message}</p>`,{confirm:callback});$('#saveModal').textContent='Confirm';}
  function exportCSV(filename,rows){if(!rows.length){toast('No records to export','error');return;}const cols=[...new Set(rows.flatMap(r=>Object.keys(r)))];const csv=[cols.join(','),...rows.map(r=>cols.map(c=>`"${String(r[c]??'').replace(/"/g,'""')}"`).join(','))].join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);toast('CSV export downloaded.');}
  function backup(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`hostelos-backup-${today()}.json`;a.click();URL.revokeObjectURL(url);toast('JSON backup downloaded.');}
  function loadMap(){if(typeof L==='undefined'){toast('Map library unavailable. Check your internet connection.','error');return;}const box=$('#movementMap');if(!box)return;box.innerHTML='';map=L.map(box).setView([Number(db.settings.hostelLat)||25.282,Number(db.settings.hostelLng)||82.956],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors',maxZoom:19}).addTo(map);L.marker([Number(db.settings.hostelLat)||25.282,Number(db.settings.hostelLng)||82.956]).addTo(map).bindPopup(`<b>${esc(db.settings.hostelName)}</b><br>Hostel location`);const active=db.passes.filter(p=>['Active','Overdue'].includes(p.status));active.forEach((p,i)=>{const lat=Number(db.settings.hostelLat)+(i%2?0.025:-0.018),lng=Number(db.settings.hostelLng)+(i%2?-0.02:0.018);L.marker([lat,lng]).addTo(map).bindPopup(`<b>${esc(studentName(p.studentId))}</b><br>${esc(p.type)}<br>SIMULATED LOCATION`);if(p.type!=='Home Pass')L.circle([Number(db.settings.hostelLat),Number(db.settings.hostelLng)],{radius:(p.radius||db.settings.localRadius)*1000,color:p.status==='Overdue'?'#d74b58':'#4b68ed',fillOpacity:.06}).addTo(map);});setTimeout(()=>map?.invalidateSize(),100);}
  function simulateLocation(){const pass=db.passes.find(p=>p.id===$('#simStudent')?.value);if(!pass)return toast('No active pass selected','error');const result=$('#simResult').value;if(result==='stale'){db.locations.unshift({id:id('LOC'),passId:pass.id,studentId:pass.studentId,recordedAt:nowISO(),status:'Stale',simulated:true});log(`Stale location update simulated for ${studentName(pass.studentId)}`,'orange');save();toast('Stale update recorded; no violation created.','error');return;}const outside=result==='outside';const loc={id:id('LOC'),passId:pass.id,studentId:pass.studentId,recordedAt:nowISO(),status:outside?'Outside boundary':'Inside boundary',simulated:true,lat:Number(db.settings.hostelLat)+(outside?.1:.005),lng:Number(db.settings.hostelLng)+(outside?.1:.005)};db.locations.unshift(loc);if(outside){db.violations.unshift({id:id('VIO'),passId:pass.id,studentId:pass.studentId,locationId:loc.id,createdAt:nowISO(),resolved:false,simulated:true});db.alerts.unshift({id:id('AL'),type:'Geofence violation',severity:'High',studentId:pass.studentId,passId:pass.id,message:'Simulated location is outside the permitted area. Verify with the student.',createdAt:nowISO(),status:'Open'});log(`Simulated geofence alert created for ${studentName(pass.studentId)}`,'red');save();renderPage();toast('Demo geofence alert created.','error');}else{log(`Inside-boundary location simulated for ${studentName(pass.studentId)}`,'green');save();toast('Inside-boundary demo update recorded.');}}
  function handleAction(action,el){
    const rid=el.dataset.id;let rec;
    switch(action){
      case 'add-student':recordForm('student');break;
      case 'edit-student':rec=student(rid);if(rec)recordForm('student',rec);break;
      case 'view-student':rec=student(rid);if(rec)viewStudent(rec);break;
      case 'delete-student':rec=student(rid);if(rec)confirmAction('Deactivate student?',`Deactivate ${rec.name}? Historical passes and attendance will be kept.`,()=>{rec.status='Inactive';log(`Student deactivated: ${rec.name}`,'orange');save();closeModal();renderPage();toast('Student deactivated.');});break;
      case 'add-room':recordForm('room');break;
      case 'edit-room':rec=room(rid);if(rec)recordForm('room',rec);break;
      case 'room-students':rec=room(rid);if(rec){const residents=db.students.filter(s=>s.roomId===rid);openModal(`Room ${rec.number} residents`,`${rec.block} · ${residents.length}/${rec.capacity} beds occupied`,residents.map(s=>`<div class="setting-row"><div><strong>${esc(s.name)}</strong><small>${esc(s.id)} · Bed ${esc(s.bed||'—')}</small></div>${status(s.status)}</div>`).join('')||'<p>No residents assigned.</p>',null);$('#saveModal').style.display='none';$('#cancelModal').textContent='Close';}break;
      case 'add-pass':recordForm('pass');break;
      case 'approve-pass':rec=db.passes.find(p=>p.id===rid);if(rec){rec.status='Approved';const a=db.alerts.find(a=>a.passId===rid&&a.type==='Pending approval'&&a.status==='Open');if(a)a.status='Resolved';log(`Pass approved for ${studentName(rec.studentId)}`,'green');save();renderPage();toast('Pass approved.');}break;
      case 'reject-pass':rec=db.passes.find(p=>p.id===rid);if(rec)confirmAction('Reject pass?',`Reject the ${rec.type} for ${studentName(rec.studentId)}?`,()=>{rec.status='Rejected';rec.tracking=false;log(`Pass rejected for ${studentName(rec.studentId)}`,'red');save();closeModal();renderPage();toast('Pass rejected.');});break;
      case 'depart-pass':rec=db.passes.find(p=>p.id===rid);if(rec&&rec.status==='Approved'){rec.status='Active';rec.actualDeparture=nowISO();rec.tracking=!!db.settings.trackingEnabled;log(`Departure recorded for ${studentName(rec.studentId)}`,'blue');save();renderPage();toast('Departure recorded.');}break;
      case 'return-pass':rec=db.passes.find(p=>p.id===rid);if(rec){rec.status='Returned';rec.actualReturn=nowISO();rec.tracking=false;db.alerts.filter(a=>a.passId===rid&&a.status!=='Resolved').forEach(a=>a.status='Resolved');log(`Return recorded for ${studentName(rec.studentId)}`,'green');save();renderPage();toast('Student return recorded.');}break;
      case 'view-pass':rec=db.passes.find(p=>p.id===rid);if(rec)viewPass(rec);break;
      case 'pass-filter':window.passFilter=el.dataset.filter;renderPage();break;
      case 'refresh-movement':checkOverdue();renderPage();toast('Movement status refreshed.');break;
      case 'load-map':loadMap();break;
      case 'simulate-location':simulateLocation();break;
      case 'save-attendance':{const date=$('#attendanceDate').value,session=$('#attendanceSession').value;if(!date)return toast('Choose an attendance date','error');$$('.attendance-choice').forEach(sel=>{if(!sel.value)return;let a=db.attendance.find(a=>a.studentId===sel.dataset.student&&a.date===date&&a.session===session);if(a){a.status=sel.value;a.markedAt=nowISO();}else db.attendance.unshift({id:id('ATT'),studentId:sel.dataset.student,date,session,status:sel.value,markedAt:nowISO()});});log(`Attendance saved for ${date} (${session})`,'green');save();renderPage();toast('Attendance saved.');break;}
      case 'add-event':recordForm('event');break;
      case 'edit-event':rec=db.events.find(e=>e.id===rid);if(rec)recordForm('event',rec);break;
      case 'delete-event':rec=db.events.find(e=>e.id===rid);if(rec)confirmAction('Delete event?',`Delete "${rec.title}"?`,()=>{db.events=db.events.filter(e=>e.id!==rid);log(`Event deleted: ${rec.title}`,'orange');save();closeModal();renderPage();toast('Event deleted.');});break;
      case 'ack-alert':rec=db.alerts.find(a=>a.id===rid);if(rec){rec.status=rec.status==='Open'?'Acknowledged':'Resolved';log(`Alert ${rec.status.toLowerCase()}: ${rec.id}`,'orange');save();renderPage();toast(`Alert ${rec.status.toLowerCase()}.`);}break;
      case 'clear-resolved':db.alerts=db.alerts.filter(a=>a.status!=='Resolved');save();renderPage();toast('Resolved alerts cleared.');break;
      case 'toggle-setting':db.settings[el.dataset.key]=!db.settings[el.dataset.key];save();renderPage();toast('Setting updated.');break;
      case 'save-settings':{const name=$('#setHostelName').value.trim(),warden=$('#setWardenName').value.trim(),lat=Number($('#setLat').value),lng=Number($('#setLng').value),lr=Number($('#setLocalRadius').value),mr=Number($('#setMainRadius').value);if(!name||!warden||!Number.isFinite(lat)||!Number.isFinite(lng)||lr<=0||mr<=0)return toast('Enter valid settings values.','error');Object.assign(db.settings,{hostelName:name,wardenName:warden,hostelLat:lat,hostelLng:lng,localRadius:lr,mainRadius:mr});save();renderPage();toast('Settings saved.');break;}
      case 'backup-data':backup();break;
      case 'reset-data':confirmAction('Restore demo data?', 'This replaces all current browser data with the original sample records. Export a backup first if needed.',()=>{db=seed();save();closeModal();go('dashboard');toast('Demo data restored.');});break;
      case 'export-students':exportCSV('hostelos-students.csv',db.students);break;
      case 'export-passes':exportCSV('hostelos-passes.csv',db.passes);break;
      case 'export-attendance':exportCSV('hostelos-attendance.csv',db.attendance);break;
      case 'export-events':exportCSV('hostelos-events.csv',db.events);break;
    }
  }
  document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){go(nav.dataset.page);return;}const actionEl=e.target.closest('[data-action]');if(actionEl){handleAction(actionEl.dataset.action,actionEl);return;}});
  $('#navigation').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page);});
  $('#modalForm').addEventListener('submit',e=>{if(modalConfig?.confirm){e.preventDefault();const cb=modalConfig.confirm;$('#saveModal').textContent='Save changes';$('#saveModal').style.display='';$('#cancelModal').textContent='Cancel';cb();return;}saveForm(e);});
  $('#closeModal').addEventListener('click',()=>{closeModal();$('#saveModal').style.display='';$('#saveModal').textContent='Save changes';$('#cancelModal').textContent='Cancel';});
  $('#cancelModal').addEventListener('click',()=>{closeModal();$('#saveModal').style.display='';$('#saveModal').textContent='Save changes';$('#cancelModal').textContent='Cancel';});
  $('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop')){closeModal();$('#saveModal').style.display='';$('#saveModal').textContent='Save changes';$('#cancelModal').textContent='Cancel';}});
  $('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
  $('#topAlerts').addEventListener('click',()=>go('alerts'));
  $('#helpBtn').addEventListener('click',()=>openModal('Quick guide','Get started with the HostelOS demo',`<div class="activity-list">${['Add students and assign them to rooms.','Create a pass and approve it from Pass Management.','Record departure to make an approved pass active.','Use Live Movement to load the map or simulate an inside/outside location update.','Record attendance and create hostel events.','Export CSV reports or download a JSON backup from Settings.'].map((x,i)=>`<div class="activity"><div class="activity-dot tone-blue">${i+1}</div><div class="activity-copy"><p>${x}</p></div></div>`).join('')}</div><div class="notice info" style="margin-top:15px">This is a frontend prototype. Data is stored only in this browser. Do not use real sensitive student information until a secure backend is implemented.</div>`,null));
  $('#resetBtn').addEventListener('click',()=>handleAction('reset-data',{}));
  $('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){currentStudentFilter=e.target.value;go('students');$('#studentSearch').value=currentStudentFilter;}});
  $('#pageContent').addEventListener('input',e=>{if(e.target.id==='studentSearch'){currentStudentFilter=e.target.value;const rows=$('#studentRows');if(!rows)return;const q=currentStudentFilter.toLowerCase();rows.innerHTML=db.students.filter(s=>[s.name,s.id,s.department,s.course,s.roomId,s.phone].join(' ').toLowerCase().includes(q)).map(s=>`<tr><td>${studentCell(s)}</td><td>${esc(s.course)}<small style="display:block;color:#9aa4b7;margin-top:3px">${esc(s.department)} · ${esc(s.year)}</small></td><td>${esc(room(s.roomId)?.number||'Unassigned')} · ${esc(s.bed||'—')}</td><td>${esc(s.phone||'—')}</td><td>${status(s.status)}</td><td>${status(movementStatus(s))}</td><td><div class="row-actions"><button class="action-btn" data-action="view-student" data-id="${s.id}">⌕</button><button class="action-btn" data-action="edit-student" data-id="${s.id}">✎</button><button class="action-btn" data-action="delete-student" data-id="${s.id}">⋯</button></div></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty-state">No matching students.</div></td></tr>'; }});
  $('#pageContent').addEventListener('change',e=>{
    if(e.target.id==='studentStatusFilter'){const val=e.target.value;$$('#studentRows tr').forEach(tr=>{tr.style.display=!val||tr.children[4]?.textContent.trim()===val?'':'none';});}
    if(e.target.id==='roomBlockFilter'){const val=e.target.value;$$('#roomCards .room-card').forEach((card,i)=>{card.style.display=!val||db.rooms[i]?.block===val?'':'none';});}
    if(e.target.id==='attendanceDate'){window.attendanceDate=e.target.value;renderPage();}
    if(e.target.id==='attendanceSession'){window.attendanceSession=e.target.value;renderPage();}
    if(e.target.id==='alertFilter'){const val=e.target.value;$$('#alertList .alert-item').forEach(a=>a.style.display=!val||a.dataset.alertStatus===val?'':'none');}
  });
  const originalHandle=handleAction;
  // Modal actions need a one-shot confirm callback, handled by submit.
  renderPage();
})();